/**
 * The site-facing catalog: metadata plus the live components.
 *
 * The component map is GENERATED by `scripts/build-registry.ts`, so adding a
 * footer is a two-step change — write the file, add its metadata. There is no
 * manual registration to forget.
 *
 * Convention: a footer's component is its DEFAULT export.
 */

import type { ComponentType } from "react";

import { COMPONENTS } from "./generated/components";
import { FOOTERS } from "./footers-meta";

export type FooterEntry = {
  readonly name: string;
  readonly title: string;
  readonly description: string;
  readonly dependencies: readonly string[];
  readonly meta: (typeof FOOTERS)[number]["meta"];
  readonly Component: ComponentType<Record<string, unknown>>;
};

export const footers: readonly FooterEntry[] = FOOTERS.map((entry) => {
  const Component = COMPONENTS[entry.name];
  if (!Component) {
    throw new Error(
      `No component registered for footer "${entry.name}". Run \`pnpm registry:build\` to regenerate.`,
    );
  }
  return { ...entry, Component };
});

export function getFooter(name: string): FooterEntry | undefined {
  return footers.find((footer) => footer.name === name);
}

export { FOOTERS, FOOTER_NAMES } from "./footers-meta";
export * from "./schema";
